#!/usr/bin/env node

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";

export const REQUEST_ENVELOPE_SCHEMA_VERSION = 1;
export const DEFAULT_REQUEST_PATH = "dev_scripts/github-filepatcher.json";

function parseArgs(argv) {
  const args = { command: null, values: new Map(), flags: new Set() };
  const tokens = [...argv];
  if (tokens[0] && !tokens[0].startsWith("--")) args.command = tokens.shift();
  while (tokens.length) {
    const token = tokens.shift();
    if (!token.startsWith("--")) continue;
    const key = token.slice(2);
    if (tokens[0] && !tokens[0].startsWith("--")) args.values.set(key, tokens.shift());
    else args.flags.add(key);
  }
  return args;
}

function stringValue(args, key, fallback = "") {
  return String(args.values.get(key) ?? fallback).trim();
}

function normalizeRepoPath(value) {
  return String(value ?? "").replaceAll("\\", "/").replace(/^\.\//, "");
}

function normalizeStringArray(value) {
  if (value === undefined || value === null) return [];
  const input = Array.isArray(value) ? value : [value];
  return [...new Set(input.map(entry => String(entry ?? "").trim()).filter(Boolean))];
}

export function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (!value || typeof value !== "object") return value;
  return Object.fromEntries(
    Object.keys(value)
      .sort()
      .map(key => [key, stableValue(value[key])])
  );
}

export function semanticRequestProjection(request) {
  const projection = { ...(request ?? {}) };
  for (const key of [
    "id",
    "description",
    "orchestrator",
    "telemetry",
    "execution_metadata",
    "runtime_metadata",
    "request_id",
    "request_fingerprint",
    "request_envelope",
    "toolchain_artifacts",
    "result"
  ]) {
    delete projection[key];
  }
  return stableValue(projection);
}

export function fingerprintRequest(request) {
  const canonical = JSON.stringify(semanticRequestProjection(request));
  return crypto.createHash("sha256").update(canonical, "utf8").digest("hex");
}

function slugRequestId(value) {
  return String(value || "request")
    .trim()
    .replace(/[^A-Za-z0-9._-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 72) || "request";
}

export function buildRequestIdentity(request, requestPath = DEFAULT_REQUEST_PATH) {
  const fingerprint = fingerprintRequest(request);
  const requestedId = slugRequestId(request?.id);
  return {
    id: `${requestedId}-${fingerprint.slice(0, 12)}`,
    fingerprint,
    fingerprint_short: fingerprint.slice(0, 12),
    request_path: normalizeRepoPath(requestPath)
  };
}

function operationPaths(request) {
  const paths = [];
  for (const operation of Array.isArray(request?.operations) ? request.operations : []) {
    if (typeof operation?.path === "string" && operation.path.trim()) paths.push(normalizeRepoPath(operation.path));
    if (Array.isArray(operation?.roots)) {
      for (const root of operation.roots) {
        if (typeof root === "string" && root.trim()) paths.push(normalizeRepoPath(root));
      }
    }
    if (typeof operation?.from === "string" && operation.from.trim()) paths.push(normalizeRepoPath(operation.from));
    if (typeof operation?.to === "string" && operation.to.trim()) paths.push(normalizeRepoPath(operation.to));
  }
  return [...new Set(paths)].sort();
}

function declaredAllowedPaths(request) {
  const allowed = request?.policy?.allowed_paths;
  if (!Array.isArray(allowed)) return [];
  return [...new Set(allowed.map(normalizeRepoPath).filter(Boolean))].sort();
}

function normalizeEvidence(value) {
  if (!Array.isArray(value)) return [];
  return value.map(entry => {
    if (typeof entry === "string") return { kind: "note", value: entry };
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) return null;
    return stableValue(entry);
  }).filter(Boolean);
}

function normalizeArtifactManifest(value) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const output = {};
  for (const [name, artifact] of Object.entries(source)) {
    if (artifact === null || artifact === undefined) continue;
    if (typeof artifact === "string") output[name] = { ref: artifact };
    else if (typeof artifact === "object" && !Array.isArray(artifact)) output[name] = stableValue(artifact);
  }
  return stableValue(output);
}

export function buildRequestEnvelope(request, requestPath = DEFAULT_REQUEST_PATH, options = {}) {
  if (!request || typeof request !== "object" || Array.isArray(request)) {
    throw new Error("Request Envelope requires a request object.");
  }

  const identity = buildRequestIdentity(request, requestPath);
  const goal = String(request.planning_goal ?? request.goal ?? "").trim();
  const acceptanceCriteria = normalizeStringArray(
    request.acceptance_criteria ?? request.acceptanceCriteria
  );
  const nonGoals = normalizeStringArray(request.non_goals ?? request.nonGoals);
  const explicitScope = normalizeStringArray(request.scope).map(normalizeRepoPath);
  const affectedPaths = operationPaths(request);
  const allowedPaths = declaredAllowedPaths(request);
  const evidence = normalizeEvidence(request.evidence);
  const artifacts = normalizeArtifactManifest(
    options.artifacts ?? request.toolchain_artifacts
  );

  const envelope = {
    schema_version: REQUEST_ENVELOPE_SCHEMA_VERSION,
    kind: "frame_conn_request_envelope",
    request: identity,
    intent: {
      goal: goal || null,
      acceptance_criteria: acceptanceCriteria,
      non_goals: nonGoals
    },
    scope: {
      explicit: [...new Set(explicitScope)].sort(),
      allowed_paths: allowedPaths,
      operation_paths: affectedPaths
    },
    evidence,
    manifest: {
      artifacts,
      result: options.result ?? request.result ?? null
    },
    source: {
      request_path: normalizeRepoPath(requestPath),
      authored_id: typeof request.id === "string" ? request.id : null,
      description: typeof request.description === "string" ? request.description : null,
      schema_version: request.schema_version ?? null,
      operation_count: Array.isArray(request.operations) ? request.operations.length : 0
    },
    authority: {
      authoritative_for: [
        "semantic_request_identity",
        "request_goal",
        "acceptance_criteria",
        "non_goals",
        "declared_scope",
        "request_artifact_index"
      ],
      not_authoritative_for: [
        "architectural_ownership",
        "patch_corridor_certification",
        "mutation_operations",
        "validation",
        "promotion"
      ]
    }
  };

  envelope.envelope_fingerprint = crypto
    .createHash("sha256")
    .update(JSON.stringify(stableValue(envelope)), "utf8")
    .digest("hex");

  return envelope;
}

export function buildRequestEnvelopeFromFile(requestPath = DEFAULT_REQUEST_PATH, options = {}) {
  const absolute = path.resolve(requestPath);
  const request = JSON.parse(fs.readFileSync(absolute, "utf8"));
  return {
    request,
    envelope: buildRequestEnvelope(request, requestPath, options)
  };
}

function writeJson(filePath, value) {
  const absolute = path.resolve(filePath);
  fs.mkdirSync(path.dirname(absolute), { recursive: true });
  fs.writeFileSync(absolute, `${JSON.stringify(value, null, 2)}\n`, "utf8");
}

function printSummary(envelope) {
  console.log(`Request Envelope: ${envelope.request.id}`);
  console.log(`request_fingerprint=${envelope.request.fingerprint}`);
  console.log(`envelope_fingerprint=${envelope.envelope_fingerprint}`);
  console.log(`goal=${envelope.intent.goal ?? ""}`);
  console.log(`acceptance_criteria=${envelope.intent.acceptance_criteria.length}`);
  console.log(`non_goals=${envelope.intent.non_goals.length}`);
  console.log(`operation_paths=${envelope.scope.operation_paths.length}`);
}

function runSelfTest() {
  const requestA = {
    schema_version: 2,
    id: "scan-fix",
    description: "First label",
    planning_goal: "Route Scan through native execution.",
    acceptance_criteria: ["Uses native Scan execution", "Preserves existing targeting"],
    non_goals: ["Do not redesign the action menu"],
    policy: { max_files_changed: 2, allowed_paths: ["scripts/a.js", "scripts/b.js"] },
    operations: [
      { type: "replace_text", path: "scripts/a.js", search: "old", replace: "new" }
    ],
    evidence: [{ kind: "native_contract", ref: "scan" }]
  };
  const requestB = {
    ...requestA,
    id: "renamed-request",
    description: "Different human label"
  };
  const requestC = {
    ...requestA,
    planning_goal: "Route Scan through a different execution path."
  };

  const envelopeA = buildRequestEnvelope(requestA, "dev_scripts/github-filepatcher.json");
  const envelopeB = buildRequestEnvelope(requestB, "dev_scripts/github-filepatcher.json");
  const envelopeC = buildRequestEnvelope(requestC, "dev_scripts/github-filepatcher.json");

  const checks = [
    envelopeA.request.fingerprint === envelopeB.request.fingerprint,
    envelopeA.request.fingerprint !== envelopeC.request.fingerprint,
    envelopeA.intent.acceptance_criteria.length === 2,
    envelopeA.intent.non_goals.length === 1,
    envelopeA.scope.operation_paths.includes("scripts/a.js"),
    envelopeA.scope.allowed_paths.length === 2,
    envelopeA.evidence[0]?.kind === "native_contract",
    /^[a-f0-9]{64}$/.test(envelopeA.request.fingerprint),
    /^[a-f0-9]{64}$/.test(envelopeA.envelope_fingerprint)
  ];
  if (checks.some(check => !check)) throw new Error("Request Envelope self-test failed.");
  console.log("Request Envelope self-test passed.");
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.flags.has("self-test") || args.command === "self-test") {
    runSelfTest();
    return;
  }

  const command = args.command || "build";
  if (!["build", "show"].includes(command)) {
    throw new Error("Usage: request-envelope.mjs [build|show|self-test] --request <file> [--output <file>]");
  }

  const requestPath = stringValue(args, "request", DEFAULT_REQUEST_PATH);
  const { envelope } = buildRequestEnvelopeFromFile(requestPath);
  const output = stringValue(args, "output");

  if (output) writeJson(output, envelope);
  if (command === "show" || !output) process.stdout.write(`${JSON.stringify(envelope, null, 2)}\n`);
  printSummary(envelope);
}

const invokedDirectly = process.argv[1]
  ? pathToFileURL(path.resolve(process.argv[1])).href === import.meta.url
  : false;

if (invokedDirectly) {
  main().catch(error => {
    console.error(error?.stack || error?.message || String(error));
    process.exitCode = 1;
  });
}

